  "plan": [
    {
      "step": 6,
      "server": "DEX Paprika",
      "tool": "search",
      "parameters": {
        "network": "ethereum",
        "chain": "uniswap_v3",
        "query": "Uniswap V3 top 5 pools by volume - daily price history"
      },
      "depends_on": [2, 4]
    },
     {
      "step": 7,
      "server": "DEX Paprika",
      "tool": "search",
      "parameters": {
        "network": "polygon",
        "chain": "quickswap",
        "query": "QuickSwap top 5 pools by volume - daily price history"
      },
      "depends_on": [2, 5]
    }
  ],
  "final_answer": "A comprehensive report detailing the top five trading pools on Uniswap V3 (Ethereum) and QuickSwap (Polygon), including their addresses, volume statistics, daily price histories, volatility percentages, transaction counts, and cross-chain token information. This data will be sourced from DEX Paprika."
}
